{
  "initial_state": "arrival_settling",
  "states": [
    {
      "id": "arrival_settling",
      "description": "Person arrives home, adjusts environment, and settles on the sofa.",
      "rules": [
        {
          "trigger": "Person enters through front door",
          "action": "Turn on air conditioner and set temperature to 26°C"
        },
        {
          "trigger": "Person sits on sofa",
          "action": "Open refrigerator, pick cola, place cola on side table, close refrigerator"
        },
        {
          "trigger": "refrigerator · door has been open for 1 minute",
          "action": "Close refrigerator"
        }
      ],
      "next": [
        {
          "to": "laundry_transfer",
          "on": "washing machine · cycle finished"
        }
      ]
    },
    {
      "id": "laundry_transfer",
      "description": "Washing machine cycle completes and laundry is moved to the dryer.",
      "rules": [
        {
          "trigger": "washing machine · cycle finished",
          "action": "Open washing machine, pick laundry, place laundry inside dryer, close dryer, set dryer start"
        }
      ],
      "next": [
        {
          "to": "snack_cleanup",
          "on": "refrigerator · door opened"
        }
      ]
    },
    {
      "id": "snack_cleanup",
      "description": "Person consumes a snack and cleans up the used cup.",
      "rules": [
        {
          "trigger": "Person leaves the empty cup on the kitchen counter",
          "action": "Open dishwasher, pick cup from kitchen counter, place cup inside dishwasher, close dishwasher"
        }
      ],
      "next": []
    }
  ]
}
